package net.minecraft.world.item;import java.util.*;import net.minecraft.world.entity.EquipmentSlot;public class ItemStack{public static final ItemStack EMPTY=new ItemStack("minecraft:air",0);public int ammo=30;public String gunId="tacz:m4a1",laser="";public String id;public int count,damage;public Map<Object,Object> components=new HashMap<>();public ItemStack(String id,int n){this.id=id;count=n;}public ItemStack copy(){ItemStack n=new ItemStack(id,count);n.components.putAll(components);n.damage=damage;n.ammo=ammo;n.gunId=gunId;n.laser=laser;return n;}public ItemStack copyWithCount(int c){ItemStack s=copy();s.count=c;return s;}public Object getItem(){if(id.equals("minecraft:cobblestone")||id.equals("minecraft:dirt"))return new BlockItem(id);return id.equals("tacz:attachment")?mod.cdv.tnpc.tactical.AttachmentFixture.ITEM:id.endsWith("_helmet")?mod.cdv.tnpc.tactical.ArmorFixture.ITEM:id.equals("tacz:gun")?mod.cdv.tnpc.tactical.GunFixture.ITEM:id;}public int getCount(){return count;}public void setCount(int n){count=n;}public boolean isEmpty(){return count<=0||id.equals("minecraft:air");}public void shrink(int n){count=Math.max(0,count-n);}public void grow(int n){count+=n;}public int getMaxStackSize(){return 64;}public int getDamageValue(){return damage;}public void setDamageValue(int n){damage=n;}public Object get(Object k){return components.get(k);}public Object set(Object k,Object v){return components.put(k,v);}public static ItemStack parseOptional(Object access,Object tag){return EMPTY;}public static boolean isSameItemSameComponents(ItemStack a,ItemStack b){return a.id.equals(b.id)&&a.components.equals(b.components);}public boolean canEquip(EquipmentSlot slot,Object n){return id.endsWith(slot==EquipmentSlot.HEAD?"_helmet":slot==EquipmentSlot.CHEST?"_chestplate":slot==EquipmentSlot.LEGS?"_leggings":"_boots");}}